package com.example.kotlin_movie_app.core.data.remoteimport com.google.gson.GsonBuilderimport okhttp3.OkHttpClientimport retrofit2.Retrofitimport retrofit2.converter.gson.GsonConverterFactoryobject Api {    private const val URL = "10.0.2.2:3000"    private const val HTTP_URL = "http://$URL/"    const val WS_URL = "ws://$URL"    private var gson = GsonBuilder().create()    val tokenInterceptor = TokenInterceptor()    val okHttpClient = OkHttpClient.Builder().apply { this.addInterceptor(tokenInterceptor) }.build()    val retrofit: Retrofit = Retrofit.Builder()        .baseUrl(HTTP_URL)        .addConverterFactory(GsonConverterFactory.create(gson))        .build()}